/**
 * Writes `changelog.md`, `changelog.xml` and `changelog-breaking.xml` into the
 * frontend build (issue #97, D184; the feeds D212): the public text of
 * `CHANGELOG.md` and its two Atom feeds, every version and the versions with
 * a Breaking, Deprecated or Notice paragraph (D224), all generated by
 * `changelog.mjs`, which
 * also writes the body of the page `/changelog` when Vite builds it. Fails,
 * and with it the build, when a version has no date or does not open with a
 * bold headline.
 *
 * Runs in `npm run build`, and so in the frontend image build, which copies
 * `CHANGELOG.md` in before it builds. Nothing it writes is committed. nginx
 * serves each file from its own location, the text as
 * `text/markdown; charset=utf-8` and the feeds as
 * `application/atom+xml; charset=utf-8` (nginx.conf); the dev server serves
 * them through `vite.config.ts`.
 *
 * Usage: node scripts/build-changelog.mjs [dist directory] [source]
 *
 * The source is the repository's `CHANGELOG.md` unless another file is given,
 * which a test build does to show what a sample entry becomes.
 */
import { Buffer } from 'node:buffer';
import console from 'node:console';
import { mkdirSync, writeFileSync } from 'node:fs';
import { join, resolve } from 'node:path';
import process from 'node:process';
import { changelogFeed, changelogMarkdown, FEEDS, readChangelog } from './changelog.mjs';

const dist = resolve(process.argv[2] ?? 'dist');
const entries =
  process.argv[3] === undefined ? readChangelog() : readChangelog(resolve(process.argv[3]));
const text = changelogMarkdown(entries);

mkdirSync(dist, { recursive: true });
writeFileSync(join(dist, 'changelog.md'), text);
console.log(
  `changelog: wrote changelog.md, ${entries.length} versions (${Buffer.byteLength(text)} bytes)`,
);

for (const [kind, feed] of Object.entries(FEEDS)) {
  const file = feed.path.slice(1);
  const xml = changelogFeed(entries, kind);

  writeFileSync(join(dist, file), xml);
  console.log(
    `changelog: wrote ${file}, ${entries.filter(feed.includes).length} entries (${Buffer.byteLength(xml)} bytes)`,
  );
}
